<script setup lang="ts">
import {computed,useId} from 'vue'
const props=defineProps<{courses:number[];edges:{prerequisite:number;course:number}[];cycle?:number[];order?:number[]}>()
const id='arrow-'+useId().replace(/:/g,'')
const nodes=computed(()=>props.courses.map((course,i)=>({course,x:230+155*Math.cos(i*2*Math.PI/props.courses.length-Math.PI/2),y:185+138*Math.sin(i*2*Math.PI/props.courses.length-Math.PI/2)})))
function point(c:number){return nodes.value.find(n=>n.course===c)!}
function path(e:{prerequisite:number;course:number}){const a=point(e.prerequisite),b=point(e.course);const dx=b.x-a.x,dy=b.y-a.y,len=Math.hypot(dx,dy),ux=dx/len,uy=dy/len;const reverse=props.edges.some(r=>r.course===e.prerequisite&&r.prerequisite===e.course);const offset=reverse?24:0;return `M ${a.x+ux*25} ${a.y+uy*25} Q ${(a.x+b.x)/2-uy*offset} ${(a.y+b.y)/2+ux*offset} ${b.x-ux*32} ${b.y-uy*32}`}
function highlighted(e:{prerequisite:number;course:number}){return props.cycle?.some((v,i)=>v===e.prerequisite&&props.cycle?.[i+1]===e.course)}
</script>
<template><div class="graph-wrap"><svg viewBox="0 0 460 370" role="img" aria-label="Prerequisite diagram. Arrows point from the prerequisite to the course that requires it. Equivalent list follows."><defs><marker :id="id" markerWidth="9" markerHeight="9" refX="7" refY="4.5" orient="auto"><path d="M1 1L7 4.5L1 8" fill="none" stroke="currentColor" stroke-width="1.3"/></marker></defs><path v-for="(e,i) in edges" :key="i" :d="path(e)" fill="none" :stroke="highlighted(e)?'var(--error)':'currentColor'" :stroke-width="highlighted(e)?2.5:1.3" :marker-end="`url(#${id})`" :data-prerequisite="e.prerequisite" :data-course="e.course"/><g v-for="n in nodes" :key="n.course"><circle :cx="n.x" :cy="n.y" r="24" :fill="cycle?.includes(n.course)?'var(--yellow)':'var(--surface)'" stroke="currentColor" stroke-width="1.3"/><text :class="{'highlight-node-label':cycle?.includes(n.course)}" :x="n.x" :y="n.y+5" text-anchor="middle" font-size="15">{{n.course}}</text></g></svg><p class="graph-legend">Prerequisite <span aria-hidden="true">→</span> course that requires it</p><details class="text-equivalent"><summary>Read as a list</summary><ul><li v-for="e in edges" :key="`${e.prerequisite}-${e.course}`">Course {{e.course}} requires Course {{e.prerequisite}}.</li><li v-for="c in courses.filter(c=>!edges.some(e=>e.prerequisite===c||e.course===c))" :key="c">Course {{c}} has no connections.</li></ul></details></div></template>
